def solve(s):
    """Run-length encode the input.
    Accepts a string or any iterable of characters. Returns a list of [char, count] pairs.
    """
    if s is None:
        return []
    # If it's not a string, try to convert to a string by joining its elements
    if not isinstance(s, str):
        try:
            s = ''.join(s)
        except Exception:
            # Fallback: use string representation
            s = str(s)
    if not s:
        return []
    result = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = ch
            count = 1
    result.append([prev, count])
    return result

