def solve(coins, amount):
    # DP for unbounded knapsack (coin change)
    # Initialize dp array of size amount+1 with inf, dp[0]=0
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

