from fractions import Fraction

def solve(matrix):
    # Empty matrix determinant is defined as 1
    if not matrix:
        return 1
    n = len(matrix)
    # Ensure square
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Create a copy with Fractions for exact arithmetic
    a = [[Fraction(x) for x in row] for row in matrix]
    det = Fraction(1)
    for i in range(n):
        # Find pivot
        pivot = i
        while pivot < n and a[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            # Swap rows
            a[i], a[pivot] = a[pivot], a[i]
            det *= -1
        det *= a[i][i]
        # Normalize row i
        piv_val = a[i][i]
        for j in range(i, n):
            a[i][j] /= piv_val
        # Eliminate below
        for k in range(i + 1, n):
            factor = a[k][i]
            if factor != 0:
                for j in range(i, n):
                    a[k][j] -= factor * a[i][j]
    # det currently product of pivots (already multiplied) but we also divided rows, need to multiply back by pivot values.
    # Since we multiplied det by each original pivot before normalization, the current det is correct.
    # Convert to integer (should be integer-valued)
    return int(det)

