def solve(weights, values, capacity):
    """0/1 knapsack: maximum total value with total weight <= capacity.
    Handles mismatched input lengths by considering pairs up to the shorter list.
    """
    if capacity <= 0:
        return 0
    # Pair weights and values safely
    items = list(zip(weights, values))
    if not items:
        return 0
    dp = [0] * (capacity + 1)
    for w, v in items:
        if w < 0:
            # ignore negative weights (invalid)
            continue
        # iterate backwards to enforce 0/1 usage
        for c in range(capacity, w - 1, -1):
            # dp[c-w] is safe because c>=w
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    # best value for any weight up to capacity
