def solve(matrix):
    """Determinant of integer square matrix using Bareiss algorithm.
    Empty matrix => 1.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # ensure square
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # make a copy
    A = [list(map(int, row)) for row in matrix]
    det_sign = 1
    for k in range(n-1):
        # pivot element A[k][k]
        if A[k][k] == 0:
            # find a row to swap
            swap = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            A[k], A[swap] = A[swap], A[k]
            det_sign = -det_sign
        for i in range(k+1, n):
            for j in range(k+1, n):
                # Bareiss update
                A[i][j] = (A[i][j]*A[k][k] - A[i][k]*A[k][j])
                if k > 0:
                    A[i][j] //= A[k-1][k-1]
            # optional: set A[i][k] = 0
        # after inner loops, can set column k to zeros (not needed)
    det = det_sign * A[n-1][n-1]
    return det

