def solve(line):
    """Parse a single CSV line into a list of fields.
    Fields may be quoted with double quotes. Inside quoted fields, commas are literal and a
    double double‑quote ('""') represents a literal quote.
    An empty line yields a list with a single empty string.
    """
    fields = []
    cur = []
    i = 0
    n = len(line)
    in_quote = False
    while i < n:
        ch = line[i]
        if in_quote:
            if ch == '"':
                # Check for escaped quote
                if i + 1 < n and line[i + 1] == '"':
                    cur.append('"')
                    i += 1
                else:
                    in_quote = False
                # Do not add the quote itself
            else:
                cur.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(cur))
                cur = []
            elif ch == '"':
                in_quote = True
            else:
                cur.append(ch)
        i += 1
    # Append last field
    fields.append(''.join(cur))
    return fields

