def solve(line):
    """Parse a single CSV line into fields.
    Handles quoted fields with commas and escaped double quotes ("" becomes ").
    Returns a list of strings. Empty line returns [''].
    """
    if line == '':
        return ['']
    fields = []
    i = 0
    n = len(line)
    while i <= n:
        if i == n:
            # End of line, add last field (could be empty)
            fields.append('')
            break
        if line[i] == '"':
            # Quoted field
            i += 1
            start = i
            sb = []
            while i < n:
                if line[i] == '"':
                    # Check if next char is also a quote (escaped quote)
                    if i + 1 < n and line[i+1] == '"':
                        sb.append('"')
                        i += 2
                        continue
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    sb.append(line[i])
                    i += 1
            fields.append(''.join(sb))
            # After quoted field, expect comma or end
            if i < n and line[i] == ',':
                i += 1
                continue
            elif i == n:
                continue
            else:
                # Unexpected char, treat as error by consuming until comma
                while i < n and line[i] != ',':
                    i += 1
                if i < n and line[i] == ',':
                    i += 1
                continue
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            # Skip comma
            if i < n and line[i] == ',':
                i += 1
                continue
    return fields

