def solve(grid):
    """Count islands of 1s in a possibly ragged 2D grid.
    Connectivity is 4-directional (up, down, left, right). Cells out of range or missing are ignored.
    """
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def get_neighbors(r, c):
        # Yield neighbor coordinates that exist in grid
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc
    def dfs(sr, sc):
        stack = [(sr, sc)]
        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            if grid[r][c] != 1:
                continue
            visited.add((r, c))
            for nr, nc in get_neighbors(r, c):
                if (nr, nc) not in visited and grid[nr][nc] == 1:
                    stack.append((nr, nc))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

def solve(n):
    """Return the number of prime numbers strictly less than n.
    Efficiently computes using the Sieve of Eratosthenes.
    """
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit+1:step] = b'\x00' * ((limit - start) // step + 1)
    return sum(sieve)

