def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    Each meeting is a list/tuple of two numbers [start, end].
    Meetings with start > end are considered invalid and ignored.
    A meeting may start exactly when another ends.
    """
    if not meetings:
        return 0
    valid = []
    for m in meetings:
        if not isinstance(m, (list, tuple)) or len(m) < 2:
            continue
        s, e = m[0], m[1]
        # Ensure numeric types
        if not isinstance(s, (int, float)) or not isinstance(e, (int, float)):
            continue
        if s <= e:
            valid.append((s, e))
    if not valid:
        return 0
    # Greedy by earliest finishing time
    valid.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for s, e in valid:
        if s >= current_end:
            count += 1
            current_end = e
    return count

