def solve(grid):
    """Return the number of islands in a binary grid.
    Supports rectangular or jagged grids where cells may be integers 0/1 or string '0'/'1'.
    An island is a group of adjacent land cells (value 1) connected orthogonally.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def is_land(val):
        return val == 1 or (isinstance(val, str) and val == '1')
    def dfs(r, c):
        stack = [(r, c)]
        visited.add((r, c))
        while stack:
            x, y = stack.pop()
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < len(grid[nx]):
                    if (nx, ny) not in visited and is_land(grid[nx][ny]):
                        visited.add((nx, ny))
                        stack.append((nx, ny))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if is_land(val) and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

