def solve(matrix):
    """Return the determinant of a square integer matrix.
    An empty matrix returns 1.
    Uses Gaussian elimination with rational arithmetic to avoid overflow.
    """
    from fractions import Fraction
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Convert to Fraction matrix
    A = [[Fraction(x) for x in row] for row in matrix]
    det = Fraction(1)
    for i in range(n):
        # Find pivot
        pivot = None
        for r in range(i, n):
            if A[r][i] != 0:
                pivot = r
                break
        if pivot is None:
            return 0
        if pivot != i:
            # swap rows
            A[i], A[pivot] = A[pivot], A[i]
            det *= -1
        piv_val = A[i][i]
        det *= piv_val
        # Normalize row i
        for c in range(i, n):
            A[i][c] /= piv_val
        # Eliminate below
        for r in range(i+1, n):
            factor = A[r][i]
            if factor == 0:
                continue
            for c in range(i, n):
                A[r][c] -= factor * A[i][c]
    # det is integer Fraction
    return int(det)

