def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses O(n log n) patience sorting technique.
    """
    if not nums:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an inc subseq of length i+1
    for x in nums:
        # Find leftmost index where tails[idx] >= x (since strictly increasing, we need >)
        idx = bisect.bisect_left(tails, x)
        # For strictly increasing, we should replace element equal to x also, as we cannot extend with equal.
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

