def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    Meetings are given as [start, end] where start <= end. Invalid intervals are ignored.
    A meeting may start exactly when another ends.
    """
    if not meetings:
        return 0
    # Filter out invalid or malformed meetings
    valid = []
    for m in meetings:
        try:
            s, e = m[0], m[1]
        except Exception:
            continue
        if s is None or e is None:
            continue
        # Ensure comparable; treat as numbers
        try:
            s_val = float(s)
            e_val = float(e)
        except Exception:
            continue
        if s_val <= e_val:
            valid.append((s_val, e_val))
    if not valid:
        return 0
    # Greedy by earliest finish time
    valid.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for start, end in valid:
        if start >= current_end:
            count += 1
            current_end = end
    return count

