def solve(coins, amount):
    """Return minimum number of coins to make amount using unlimited coins.
    If impossible, return -1. Coins are positive integers.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    if not coins:
        return -1
    # Remove non-positive coins
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    # DP array
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
