        # Treat list or tuple as a container to be flattened
        if isinstance(item, (list, tuple)):
            for sub in item:
                helper(sub)
        else:
            # Only accept int (excluding bool)
            if isinstance(item, int) and not isinstance(item, bool):
                result.append(item)
    helper(structure)
