def solve(grid):
    """Count islands in a binary grid.
    Accepts any rectangular 2‑D sequence (list/tuple of rows) where each cell may be an int, bool,
    or a character representing 0/1. Cells are connected 4‑directionally.
    Returns 0 for empty grid.
    """
    # Empty grid handling
    if not grid:
        return 0
    # Convert to list of rows for uniform indexing
    rows = len(grid)
    # Determine column count from first row, handling non‑list rows safely
    first_row = grid[0]
    cols = len(first_row) if hasattr(first_row, '__len__') else 0
    # Helper to decide if a cell is land (value 1)
    def is_land(val):
        # Direct int or bool
        if val == 1:
            return True
        # Character representations
        if isinstance(val, (str, bytes)) and len(val) == 1:
            return val == '1' or val == b'1'
        # Convert other types via int if possible
        try:
            return int(val) == 1
        except Exception:
            return False
    visited = [[False] * cols for _ in range(rows)]
    def bfs(r, c):
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            cr, cc = stack.pop()
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and is_land(grid[nr][nc]):
                    visited[nr][nc] = True
                    stack.append((nr, nc))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if is_land(grid[i][j]) and not visited[i][j]:
                count += 1
                bfs(i, j)
    return count

