def solve(coins, amount):
    """Return the minimum number of coins needed to make up `amount` using unlimited
    supply of each coin in `coins`. Return -1 if it cannot be formed.
    Implements classic DP (unbounded knapsack) with O(amount * len(coins)) time.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter out non-positive coin denominations
    coins = [c for c in coins if isinstance(c, int) and c > 0]
    if not coins:
        return -1
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= a:
                cand = dp[a - c] + 1
                if cand < best:
                    best = cand
        dp[a] = best
    return dp[amount] if dp[amount] != INF else -1

